CREATE EXTENSION IF NOT EXISTS vector;
CREATE TABLE IF NOT EXISTS communities (id VARCHAR(36) PRIMARY KEY, name VARCHAR(120) NOT NULL, address TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS charging_piles (id VARCHAR(36) PRIMARY KEY, community_id VARCHAR(36) NOT NULL, code VARCHAR(50) NOT NULL, status VARCHAR(20) NOT NULL, power NUMERIC(8,2) DEFAULT 0, faults INT DEFAULT 0, last_seen TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS charging_orders (id VARCHAR(36) PRIMARY KEY, user_id VARCHAR(36) NOT NULL, pile_id VARCHAR(36) NOT NULL, status VARCHAR(20) NOT NULL, amount NUMERIC(10,2) DEFAULT 0, kwh NUMERIC(10,2) DEFAULT 0, created_at TIMESTAMPTZ DEFAULT now(), idempotency_key VARCHAR(100) UNIQUE);
CREATE TABLE IF NOT EXISTS reservations (id VARCHAR(36) PRIMARY KEY, user_id VARCHAR(36) NOT NULL, pile_id VARCHAR(36) NOT NULL, starts_at TIMESTAMPTZ NOT NULL, ends_at TIMESTAMPTZ NOT NULL, status VARCHAR(20) NOT NULL);
CREATE TABLE IF NOT EXISTS device_events (id VARCHAR(36) PRIMARY KEY, pile_id VARCHAR(36) NOT NULL, event_type VARCHAR(50) NOT NULL, payload JSONB NOT NULL, occurred_at TIMESTAMPTZ NOT NULL, processed_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS repair_tickets (id VARCHAR(36) PRIMARY KEY, pile_id VARCHAR(36) NOT NULL, level VARCHAR(10) NOT NULL, title TEXT NOT NULL, status VARCHAR(20) NOT NULL, created_at TIMESTAMPTZ DEFAULT now(), closed_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS approvals (id VARCHAR(36) PRIMARY KEY, type VARCHAR(40) NOT NULL, request JSONB NOT NULL, status VARCHAR(20) NOT NULL, created_at TIMESTAMPTZ DEFAULT now(), decided_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS audit_logs (id BIGSERIAL PRIMARY KEY, trace_id VARCHAR(36), actor_id VARCHAR(36), action VARCHAR(100) NOT NULL, detail JSONB, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS short_term_memory (id BIGSERIAL PRIMARY KEY, thread_id VARCHAR(100) NOT NULL, state JSONB NOT NULL, expires_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS long_term_memory (id BIGSERIAL PRIMARY KEY, user_id VARCHAR(36), summary TEXT NOT NULL, embedding vector(1536), metadata JSONB, created_at TIMESTAMPTZ DEFAULT now());
